#!/usr/bin/env bash
# ============================================================================
# VideoMind Redesign - Part 5: Secondary screens
# ============================================================================
# Presentation only + one real link fix.
#   about/page.tsx : "See the library" button -> /library (was /, now landing)
#   v/[id]/page.tsx: section primitive on nav wrapper. Marketing "/" CTAs on
#                    the public share page are PRESERVED (they should point to
#                    the landing page - that is correct after Part 2).
# search / assistant / learn use narrower reading columns by design and are
# intentionally left as-is.
# Requires Part 1 + Part 2 applied.
#
#   ./vm_part5_secondary.sh          apply
#   ./vm_part5_secondary.sh --revert restore from backups
# ============================================================================
set -euo pipefail
ABOUT="frontend/src/app/about/page.tsx"
SHARE="frontend/src/app/v/[id]/page.tsx"
GLOBALS="frontend/src/app/globals.css"
NAV="frontend/src/components/layout/Navbar.tsx"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR="frontend/.vm_part5_backups"
say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }
[ -f "$ABOUT" ] || die "$ABOUT not found. Run from repo root (folder containing frontend/)."

if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir. Nothing to revert."
  LATEST="$(ls -1d $BAKDIR/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  cp "$LATEST/about.tsx" "$ABOUT"
  cp "$LATEST/share.tsx" "$SHARE"
  say "Reverted about + share from $LATEST"
  exit 0
fi

grep -q "VM_PART1_FOUNDATION" "$GLOBALS" 2>/dev/null || die "Part 1 not applied first."
grep -q '"/library"' "$NAV" 2>/dev/null || die "Part 2 not applied first."
if grep -q 'href="/library"' "$ABOUT" 2>/dev/null && grep -q 'className="section' "$SHARE" 2>/dev/null; then
  say "Part 5 already applied. Use --revert to undo."; exit 0
fi

mkdir -p "$BAKDIR/$STAMP"
cp "$ABOUT" "$BAKDIR/$STAMP/about.tsx"
cp "$SHARE" "$BAKDIR/$STAMP/share.tsx"
say "Backups saved to $BAKDIR/$STAMP/"

decode() {
  local tmp; tmp="$(mktemp)"
  printf '%s' "$1" | base64 -d > "$tmp" || die "$3: base64 decode failed."
  grep -q "$2" "$tmp" || die "$3: payload verify failed (missing '$2'). Nothing written."
  printf '%s' "$tmp"
}
T_ABOUT="$(decode "" 'href="/library"' "about")"
T_SHARE="$(decode "" 'className="section' "share")"
# safety: share page must still carry its marketing landing CTAs
grep -c 'href="/"' "$T_SHARE" | grep -q '4' || die "share payload lost its marketing links - aborting."

cp "$T_ABOUT" "$ABOUT"; cp "$T_SHARE" "$SHARE"
rm -f "$T_ABOUT" "$T_SHARE"
grep -q 'href="/library"' "$ABOUT" || die "about verify failed - restore from $BAKDIR/$STAMP"
grep -q 'className="section' "$SHARE" || die "share verify failed."

say "Applied Part 5: about library link fixed, share page spacing aligned."
say "Next: cd frontend && npm run build"
